# Re-enable App Access to Tracking Data Write-Host "Restoring app access to personal data..." -ForegroundColor Cyan $consentStore = "HKCU:\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore" $categories = @("appDiagnostics", "contacts", "appointments", "phoneCallHistory", "email", "userDataTasks", "chat", "phoneCall", "radios") foreach ($cat in $categories) { $path = "$consentStore\$cat" if (Test-Path $path) { Set-ItemProperty -Path $path -Name "Value" -Value "Allow" -Force -ErrorAction SilentlyContinue } } Write-Host "App access to personal data has been restored." -ForegroundColor Green